report_script:
filters = filters or {}

# --------------------------------
# Conditions
# --------------------------------

where_clauses = [
    "docstatus < 2",
    "item_group IN ('Sub Assembly', 'Assembly', 'General Assembly')"
]
params = {}

if filters.get("from_date"):
    where_clauses.append("creation >= %(from_date)s")
    params["from_date"] = filters["from_date"]

if filters.get("to_date"):
    where_clauses.append("creation <= %(to_date)s")
    params["to_date"] = filters["to_date"]

if filters.get("bom_type"):
    where_clauses.append("item_group = %(bom_type)s")
    params["bom_type"] = filters["bom_type"]

where_sql = " AND ".join(where_clauses)

# --------------------------------
# Query
# --------------------------------

query = f"""

SELECT

    creation,
    item_group

FROM `tabBOM`

WHERE {where_sql}

ORDER BY creation

"""

result = frappe.db.sql(query, params, as_dict=True)

# --------------------------------
# Month Mapping
# --------------------------------

month_map = {
    4: "apr",
    5: "may",
    6: "jun",
    7: "jul",
    8: "aug",
    9: "sep",
    10: "oct",
    11: "nov",
    12: "dec",
    1: "jan",
    2: "feb",
    3: "mar",
}

months = [
    "apr","may","jun","jul","aug","sep",
    "oct","nov","dec","jan","feb","mar"
]

# --------------------------------
# Initial Rows
# --------------------------------

rows = {

    "SBA Drawing": {
        "bom_type":"SBA Drawing"
    },

    "ASS Drawing": {
        "bom_type":"ASS Drawing"
    },

    "GA Drawing": {
        "bom_type":"GA Drawing"
    }

}

for row in rows.values():

    for m in months:

        row[m] = 0

# --------------------------------
# Populate Data
# --------------------------------

for d in result:

    month = month_map.get(d.creation.month)

    if d.item_group == "Sub Assembly":

        rows["SBA Drawing"][month] = (
            rows["SBA Drawing"][month] + 1
        )

    elif d.item_group == "Assembly":

        rows["ASS Drawing"][month] = (
            rows["ASS Drawing"][month] + 1
        )

    elif d.item_group == "General Assembly":

        rows["GA Drawing"][month] = (
            rows["GA Drawing"][month] + 1
        )

# --------------------------------
# Final Data
# --------------------------------

report_data = []

monthly_total = {
    "bom_type":"Monthly Total Qty"
}

for m in months:
    monthly_total[m] = 0

grand_total = 0

for row in rows.values():

    total = 0

    for m in months:

        total = total + row[m]

        monthly_total[m] = monthly_total[m] + row[m]

    row["year_total"] = total

    grand_total = grand_total + total

    report_data.append(row)

monthly_total["year_total"] = grand_total

report_data.append(monthly_total)

# --------------------------------
# Columns
# --------------------------------

columns = [

    {
        "label":"BOM Type",
        "fieldname":"bom_type",
        "fieldtype":"Data",
        "width":180,
    },

    {
        "label":"April",
        "fieldname":"apr",
        "fieldtype":"Int",
        "width":70,
    },

    {
        "label":"May",
        "fieldname":"may",
        "fieldtype":"Int",
        "width":70,
    },

    {
        "label":"June",
        "fieldname":"jun",
        "fieldtype":"Int",
        "width":70,
    },

    {
        "label":"July",
        "fieldname":"jul",
        "fieldtype":"Int",
        "width":70,
    },

    {
        "label":"August",
        "fieldname":"aug",
        "fieldtype":"Int",
        "width":70,
    },

    {
        "label":"September",
        "fieldname":"sep",
        "fieldtype":"Int",
        "width":80,
    },

    {
        "label":"October",
        "fieldname":"oct",
        "fieldtype":"Int",
        "width":70,
    },

    {
        "label":"November",
        "fieldname":"nov",
        "fieldtype":"Int",
        "width":80,
    },

    {
        "label":"December",
        "fieldname":"dec",
        "fieldtype":"Int",
        "width":80,
    },

    {
        "label":"January",
        "fieldname":"jan",
        "fieldtype":"Int",
        "width":70,
    },

    {
        "label":"February",
        "fieldname":"feb",
        "fieldtype":"Int",
        "width":80,
    },

    {
        "label":"March",
        "fieldname":"mar",
        "fieldtype":"Int",
        "width":70,
    },

    {
        "label":"Yearly Total",
        "fieldname":"year_total",
        "fieldtype":"Int",
        "width":120,
    }

]

# --------------------------------
# Summary
# --------------------------------

summary = [

    {
        "value": len(result),
        "label":"Total BOMs",
        "datatype":"Int"
    },

    {
        "value": grand_total,
        "label":"Yearly Total",
        "datatype":"Int"
    }

]

# --------------------------------
# Return
# --------------------------------

data = columns, report_data, None, None, summary

