frappe.query_reports["Work Order Planning Sheet"] = {

    filters: [
        {
            fieldname: "from_date",
            label: __("From Indent Date"),
            fieldtype: "Date",
            default: frappe.datetime.add_months(frappe.datetime.get_today(), -3)
        },
        {
            fieldname: "to_date",
            label: __("To Indent Date"),
            fieldtype: "Date",
            default: frappe.datetime.get_today()
        },
        {
            fieldname: "customer",
            label: __("Customer"),
            fieldtype: "Link",
            options: "Customer"
        },
        {
            fieldname: "lot_no",
            label: __("Lot No"),
            fieldtype: "Data"
        },
        {
            fieldname: "stage",
            label: __("Stage"),
            fieldtype: "Select",
            options: ""
        }
    ],

    _stageColorMap: {
        "Dispatched":             { bg: "#FF00FF", fg: "#1a1a1a" },
        "Ready for Dispatch":     { bg: "#92D050", fg: "#1a1a1a" },
        "Assembly":               { bg: "#00B050", fg: "#ffffff" },
        "Powder Coating":         { bg: "#FFFF00", fg: "#1a1a1a" },
        "Transferred to Unit 1":  { bg: "#FFB6C1", fg: "#1a1a1a" },
        "Welding":                { bg: "#CC99FF", fg: "#1a1a1a" },
        "Bending":                { bg: "#FFA500", fg: "#1a1a1a" },
        "Punching":               { bg: "#00FFFF", fg: "#1a1a1a" },
        "Programming":            { bg: "#9DC3E6", fg: "#1a1a1a" },
        "Design Received":        { bg: "#FFD9D9", fg: "#1a1a1a" },
        "Design Issued":          { bg: "#FFD9D9", fg: "#1a1a1a" },
    },

    _dynamicColorMap: {},

    _cssColorToHex: {
        "red":        { bg: "#FF0000", fg: "#ffffff" },
        "green":      { bg: "#00B050", fg: "#ffffff" },
        "blue":       { bg: "#0070C0", fg: "#ffffff" },
        "yellow":     { bg: "#FFFF00", fg: "#1a1a1a" },
        "orange":     { bg: "#FFA500", fg: "#1a1a1a" },
        "purple":     { bg: "#CC99FF", fg: "#1a1a1a" },
        "pink":       { bg: "#FFB6C1", fg: "#1a1a1a" },
        "cyan":       { bg: "#00FFFF", fg: "#1a1a1a" },
        "magenta":    { bg: "#FF00FF", fg: "#1a1a1a" },
        "white":      { bg: "#ffffff", fg: "#1a1a1a" },
        "black":      { bg: "#1a1a1a", fg: "#ffffff" },
        "grey":       { bg: "#cccccc", fg: "#1a1a1a" },
        "gray":       { bg: "#cccccc", fg: "#1a1a1a" },
        "lightblue":  { bg: "#9DC3E6", fg: "#1a1a1a" },
        "lightgreen": { bg: "#92D050", fg: "#1a1a1a" },
        "lightpink":  { bg: "#FFD9D9", fg: "#1a1a1a" },
    },

    _getRowColor: function(latest_stage) {
        if (!latest_stage) return null;
        const self = frappe.query_reports["Work Order Planning Sheet"];
        return self._dynamicColorMap[latest_stage]
            || self._stageColorMap[latest_stage]
            || null;
    },

    // ─── formatter: lot_no link is now built in Python, not here ─────────────
    formatter: function(value, row, column, data, default_formatter) {
        const self = frappe.query_reports["Work Order Planning Sheet"];
        const color = self._getRowColor(data && data.latest_stage);

        // lot_no already contains <a> tag built in Python — just wrap with color
        let cell = default_formatter(value, row, column, data);

        if (color) {
            cell = `<span style="
                display:block;width:100%;
                background-color:${color.bg};
                color:${color.fg};
                padding:2px 6px;font-weight:500;
            ">${cell}</span>`;
        }

        return cell;
    },

    get_datatable_options(options) {
        return Object.assign(options, { checkboxColumn: true });
    },

    _fetchStages: function(callback) {
        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Production Stages",
                fields: ["name", "custom_color"],
                limit_page_length: 0,
                order_by: "name asc"
            },
            callback: function(r) { callback(r.message || []); }
        });
    },

    _buildColorMap: function(stages) {
        const self = frappe.query_reports["Work Order Planning Sheet"];
        self._dynamicColorMap = {};
        stages.forEach(function(s) {
            if (!s.custom_color) return;
            const key = s.custom_color.toLowerCase().replace(/\s/g, "");
            const resolved = self._cssColorToHex[key];
            if (resolved) {
                self._dynamicColorMap[s.name] = resolved;
            } else if (s.custom_color.startsWith("#")) {
                self._dynamicColorMap[s.name] = { bg: s.custom_color, fg: "#1a1a1a" };
            }
        });
        console.log("[WO Planning] Color map:", self._dynamicColorMap);
    },

    onload: function(report) {
        const self = frappe.query_reports["Work Order Planning Sheet"];

        self._fetchStages(function(stages) {
            self._buildColorMap(stages);

            const stageNames = stages.map(s => s.name);
            const stageFilter = report.get_filter("stage");
            if (!stageFilter) return;

            const selectEl =
                (stageFilter.$select && stageFilter.$select[0]) ||
                (stageFilter.$input  && stageFilter.$input[0])  ||
                (stageFilter.wrapper && $(stageFilter.wrapper).find("select")[0]);

            if (!selectEl) return;

            const current = selectEl.value;
            selectEl.innerHTML = "";
            ["", ...stageNames].forEach(function(stage) {
                const opt = document.createElement("option");
                opt.value = stage;
                opt.textContent = stage;
                selectEl.appendChild(opt);
            });
            selectEl.value = stageNames.includes(current) ? current : "";
        });

        report.page.add_inner_button(__("Color Legend"), function() {
            self._fetchStages(function(stages) {
                self._buildColorMap(stages);

                const rows = stages.map(function(s) {
                    const color = self._getRowColor(s.name);
                    return [color ? color.bg : "#ffffff", color ? color.fg : "#1a1a1a", s.name];
                });
                rows.push(["#ffffff", "#1a1a1a", "Open / No Stage Completed"]);

                frappe.msgprint({
                    title: __("Color Legend — Work Order Planning Sheet"),
                    message: `
                        <table style="width:100%;border-collapse:collapse;font-size:13px;">
                            <thead>
                                <tr style="background:#f0f0f0;">
                                    <th style="padding:8px 12px;text-align:left;border-bottom:1px solid #ddd;">Colour</th>
                                    <th style="padding:8px 12px;text-align:left;border-bottom:1px solid #ddd;">Stage</th>
                                </tr>
                            </thead>
                            <tbody>
                                ${rows.map(([bg, fg, label]) => `
                                    <tr>
                                        <td style="padding:6px 12px;">
                                            <span style="display:inline-block;width:200px;height:26px;
                                                background:${bg};border:1px solid #bbb;border-radius:3px;
                                                color:${fg};text-align:center;line-height:26px;
                                                font-size:12px;font-weight:500;">${label}</span>
                                        </td>
                                        <td style="padding:6px 12px;color:#333;">${label}</td>
                                    </tr>`).join("")}
                            </tbody>
                        </table>`,
                    wide: true
                });
            });
        });
    }
};

frappe.query_reports["WO Hardware List"] = {
    filters: [
        {
            fieldname: "production_plan",
            label: "Production Plan",
            fieldtype: "Link",
            options: "Production Plan",
            get_query: function () {
                return {
                    filters: {
                        docstatus: 1
                    }
                };
            }
        }
    ],

    onload: function(report) {

        setTimeout(() => {

            report.page.add_inner_button("Print", function () {

                let filters = report.get_values();

                if (!filters || !filters.production_plan) {
                    frappe.msgprint("Please select Production Plan");
                    return;
                }

                // ✅ Clean value (remove "NA " if present)
                let wo_name = filters.production_plan.replace(/^NA\s+/, "");

                // STEP 1: Fetch report data
                frappe.call({
                    method: "frappe.desk.query_report.run",
                    args: {
                        report_name: "WO Hardware List",
                        filters: filters
                    },
                    callback: function(r) {

                        if (!r.message || !r.message.result || r.message.result.length === 0) {
                            frappe.msgprint("No data found");
                            return;
                        }

                        let data = r.message.result;

                        // STEP 2: Get Production Plan (your Work Order)
                        frappe.db.get_doc("Production Plan", wo_name)
                            .then(wo => {

                                let so = {};

                                if (wo.sales_order) {
                                    frappe.db.get_doc("Sales Order", wo.sales_order)
                                        .then(res => {
                                            so = res;
                                            render_print(data, filters, wo, so, wo_name);
                                        });
                                } else {
                                    render_print(data, filters, wo, so, wo_name);
                                }

                            });

                    }
                });

            });

        }, 500);
    }
};


// ✅ PRINT FUNCTION
function render_print(data, filters, wo, so, wo_name) {

    let html = `
        <html>
        <head>
            <style>
                body { font-family: Arial; font-size: 11px; }

                .header-table { width:100%; margin-bottom:10px; }

                .title { text-align:right; font-weight:bold; font-size:14px; }

                table { width:100%; border-collapse:collapse; }

                th, td {
                    border:1px solid black;
                    padding:4px;
                }

                .assembly-row {
                    font-weight:bold;
                    background:#f5f5f5;
                }

                .right { text-align:right; }

                @media print {
                    @page { size:A4; margin:10mm; }
                }
            </style>
        </head>

        <body>

        <table class="header-table">
            <tr>
                <td>
                    <b>P.O.No:</b> ${wo.custom_customer_po_no || ""}<br>
                    <b>W.O.No:</b> ${wo.name || wo_name}<br>
                    <b>Customer Code:</b> ${wo.custom_cust_code || ""}
                </td>

                <td style="text-align:right;">
                    <div class="title">WO Hardware List</div>

                    <b>P.O.Date:</b> ${
                        wo.custom_customer_po_date
                            ? frappe.datetime.str_to_user(wo.custom_customer_po_date)
                            : ""
                    }<br>

                    <b>W.O.Date:</b> ${
                        wo.posting_date
                            ? frappe.datetime.str_to_user(wo.posting_date)
                            : (wo.transaction_date
                                ? frappe.datetime.str_to_user(wo.transaction_date)
                                : "")
                    }<br>

                    <b>Type of Panel:</b> ${wo.production_item || ""}
                </td>
            </tr>
        </table>

        <table>
            <tr>
                <th>Assembly Name</th>
                <th>Item Code</th>
                <th>Item Name</th>
                <th>Unit Qty</th>
                <th>Total Qty</th>
            </tr>
    `;

    let currentAssembly = "";

    data.forEach(row => {

        if (row.item_name === "Assembly") {

            currentAssembly = row.assembly || "Assembly";

            html += `
                <tr class="assembly-row">
                    <td>${currentAssembly}</td>
                    <td></td>
                    <td>Assembly Qty</td>
                    <td></td>
                    <td class="right">${row.total_qty || 0}</td>
                </tr>
            `;

        } else {

            html += `
                <tr>
                    <td></td>
                    <td>${row.item_code || ""}</td>
                    <td>${row.item_name || ""}</td>
                    <td class="right">${row.qty || 0}</td>
                    <td class="right">${row.total_qty || 0}</td>
                </tr>
            `;
        }

    });

    html += `</table></body></html>`;

    let w = window.open("", "_blank");
    w.document.write(html);
    w.document.close();
    w.print();
}

