frappe.query_reports["Stock Statement"] = {

    onload: function (report) {
        // Pre-fetch all excluded groups (parents + descendants) from server
        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Item Group",
                filters: [
                    ["Item Group", "name", "in", ["Products", "Assembly Item", "Accessories"]]
                ],
                fields: ["name", "lft", "rgt"],
                limit: 0
            },
            callback: function (r) {
                if (!r.message) return;

                // Build a single combined lft/rgt range query to get ALL descendants
                let promises = r.message.map(function (parent) {
                    return frappe.call({
                        method: "frappe.client.get_list",
                        args: {
                            doctype: "Item Group",
                            filters: [
                                ["Item Group", "lft", ">=", parent.lft],
                                ["Item Group", "rgt", "<=", parent.rgt]
                            ],
                            fields: ["name"],
                            limit: 0
                        }
                    });
                });

                Promise.all(promises).then(function (results) {
                    let all_excluded = [];
                    results.forEach(function (res) {
                        if (res.message) {
                            res.message.forEach(function (g) {
                                all_excluded.push(g.name);
                            });
                        }
                    });

                    // Deduplicate and store on report object for use in get_query
                    report._excluded_item_groups = [...new Set(all_excluded)];
                });
            }
        });
    },

    filters: [
        {
            fieldname: "item_head",
            label: "Item Head",
            fieldtype: "Link",
            options: "Item Group",
            get_query: function () {
                let excluded = frappe.query_report._excluded_item_groups || 
                               ["Products", "Assembly Item", "Accessories"];
                return {
                    filters: [
                        ["Item Group", "name", "not in", excluded]
                    ]
                };
            }
        },
        {
            fieldname: "from_date",
            label: "From",
            fieldtype: "Date",
            default: frappe.datetime.month_start(),
            reqd: 1
        },
        {
            fieldname: "to_date",
