                return [bg, fg, s.name];
            });

            rows.push(["#ffffff", "#1a1a1a", "Open / No Stage Completed"]);

            const legendHtml = `
                <table style="width:100%;border-collapse:collapse;font-size:13px;">
                    <thead>
                        <tr style="background:#f0f0f0;">
                            <th style="padding:8px 12px;text-align:left;border-bottom:1px solid #ddd;">Colour</th>
                            <th style="padding:8px 12px;text-align:left;border-bottom:1px solid #ddd;">Stage</th>
                        </tr>
                    </thead>
                    <tbody>
                        ${rows.map(([bg, fg, label]) => `
                            <tr>
                                <td style="padding:6px 12px;">
                                    <span style="
                                        display:inline-block;
                                        width:200px;height:26px;
                                        background:${bg};
                                        border:1px solid #bbb;
                                        border-radius:3px;
                                        color:${fg};
                                        text-align:center;
                                        line-height:26px;
                                        font-size:12px;
                                        font-weight:500;
                                    ">${label}</span>
                                </td>
                                <td style="padding:6px 12px;color:#333;">${label}</td>
                            </tr>
                        `).join("")}
                    </tbody>
                </table>
            `;

            frappe.msgprint({
                title: __("Color Legend — WorkOrder Planning Sheet"),
                message: legendHtml,
                wide: true
            });
        });
    },

    onload: function(report) {
        const self = frappe.query_reports["WorkOrder Planning Sheet"];

        self._fetchStages(function(stages) {
            // Load DB colors into _dynamicColorMap (used only as fallback now)
            stages.forEach(function(s) {
                const resolved = self._resolveColorValue(s.custom_color);
                if (resolved) {
                    self._dynamicColorMap[s.name] = resolved;
                }
            });

            // Populate stage filter dropdown
            const stageNames = stages.map(function(s) { return s.name; });
            const virtualStages = [
                "Open / No Stage Completed",
                "Design Received / Design Issued"
            ];
            const allOptions = [...stageNames, ...virtualStages];

            const stageFilter = report.get_filter("stage");
            if (!stageFilter) return;

            const selectEl =
                (stageFilter.$select && stageFilter.$select[0]) ||
                (stageFilter.$input  && stageFilter.$input[0])  ||
                (stageFilter.wrapper && $(stageFilter.wrapper).find("select")[0]);

            if (!selectEl) return;

            const defaultStage = "Issue to Shop";
            const currentValue = selectEl.value;
            selectEl.innerHTML = "";

            ["", ...allOptions].forEach(function(opt) {
                const el = document.createElement("option");
                el.value = opt;
                el.textContent = opt;
                selectEl.appendChild(el);
            });

            if (!currentValue && allOptions.includes(defaultStage)) {
                selectEl.value = defaultStage;
                report.set_filter_value("stage", defaultStage);
            } else {
                selectEl.value = allOptions.includes(currentValue) ? currentValue : "";
            }
        });

        // Add button only once
        if (!self._legendButtonAdded) {
            self._legendButtonAdded = true;
            report.page.add_inner_button(__("Color Legend"), function() {
                self._showLegend();
            });
        }
    }
};
